import React from 'react';
import { FormItem, FormButtonGroup, Submit, Cascader } from '@storage-fe/formily-arco';
import { createForm, Field } from '@formily/core';
import { FormProvider, createSchemaField } from '@formily/react';
import { action } from '@formily/reactive';

const SchemaField = createSchemaField({
  components: {
    Cascader,
    FormItem,
  },
});

const transformAddress = (data = {}) =>
  Object.entries(data).reduce((buf: any, [key, value]: any) => {
    if (typeof value === 'string') {
      return buf.concat({
        label: value,
        value: key,
      });
    }
    const { name, code, cities, districts } = value;
    const _cities: any = transformAddress(cities);
    const _districts: any = transformAddress(districts);
    return buf.concat({
      label: name,
      value: code,
      children: _cities.length ? _cities : _districts.length ? _districts : undefined,
    });
  }, []);

const useAsyncDataSource = (url: string, transform: (data: any) => any) => (field: Field) => {
  field.loading = true;
  fetch(url)
    .then(res => res.json())
    .then(
      action.bound?.(data => {
        field.dataSource = transform(data);
        field.loading = false;
      })
    );
};

const form = createForm();

const schema = {
  type: 'object',
  properties: {
    address: {
      type: 'string',
      title: '地址选择',
      'x-decorator': 'FormItem',
      'x-component': 'Cascader',
      'x-component-props': {
        style: {
          width: 240,
        },
      },
      'x-reactions': ['{{useAsyncDataSource("//unpkg.com/china-location/dist/location.json",transformAddress)}}'],
    },
  },
};

export default () => (
  <FormProvider form={form}>
    <SchemaField schema={schema} scope={{ useAsyncDataSource, transformAddress }} />
    <FormButtonGroup>
      <Submit onSubmit={console.log}>提交</Submit>
    </FormButtonGroup>
  </FormProvider>
);
